import os, math, json
_P = json.loads(os.environ.get('PJ', '{}'))
def _p(k, d): return float(_P.get(k, d))
SG = _p('SG', 18); TAU = _p('TAU', 0.0); LIN = _p('LIN', 15); BETA = _p('BETA', -0.75)
SSD = _p('SSD', 0.0); L2 = _p('L2', 0.0); KM = _p('KM', 4.0); SGT = _p('SGT', SG)
LP = _p('LP', 1.0)
MEAN = 40.2
AL = [0.0]*101; BQ = [0.0]*101
for g in range(1, 101):
    if TAU > 0:
        s = 1.0 / (1.0 + math.exp(-(SG + 0.5 - g) / TAU))
    else:
        s = 1.0 if g <= SG else 0.0
    AL[g] = LIN * (g ** LP) * s + L2 * g
    BQ[g] = (1 - s) * (g / 50.0) ** BETA + s * SSD
N = [0]*101
st = [0, 0]
def priority(item, capacities):
    st[0] += 1; t = st[0]
    endgame = st[1] * KM >= MEAN * (5000 - t)
    n = len(capacities); scores = [0.0]*n
    if endgame:
        for i in range(n):
            scores[i] = -(capacities[i] - item) - (1000 if capacities[i] == 100 else 0)
    else:
        for i in range(n):
            g = capacities[i]; h = g - item; d = 0.0
            if g < 100:
                d += -AL[g] + BQ[g] * (1 - 2*N[g])
            if h > 0:
                d += AL[h] + BQ[h] * (2*N[h] + 1)
            scores[i] = -d - 1e-6*h
    best = 0; bs = scores[0]
    for i in range(1, n):
        if scores[i] > bs: bs = scores[i]; best = i
    g = capacities[best]; h = g - item
    if g < 100:
        N[g] -= 1
        if g > SGT: st[1] -= g
    if h > 0:
        N[h] += 1
        if h > SGT: st[1] += h
    return scores
