import sys, os, json, math, importlib.util, numpy as np
from multiprocessing import Pool
sys.path.insert(0, '/Users/mohammed/Desktop/creative/tasks/online_bin_packing')
from evaluator import make_items, pack
PATH = sys.argv[1]
ITEMS = {}
def run(args):
    pj, seed = args
    os.environ['PJ'] = pj
    if seed not in ITEMS: ITEMS[seed] = make_items(seed)
    items = ITEMS[seed]; lb = math.ceil(items.sum()/100)
    spec = importlib.util.spec_from_file_location("c", PATH); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    return 100.0*(pack(m.priority, items)-lb)/lb
def score(pool, p, seeds):
    return float(np.mean(pool.map(run, [(json.dumps(p), s) for s in seeds])))
if __name__ == '__main__':
